#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    long num = strtol(argv[1], NULL, 10);
    long denom = strtol(argv[2], NULL, 10);
    long remainder = num;
    int count = 0;
    long quotients[201];

    while (remainder != 0 && count < 200) {
        long quotient = remainder / denom;
        quotients[count++] = quotient;
        remainder -= quotient * denom;
        if (remainder == 0) break;
        long temp = denom;
        denom = remainder;
        remainder = temp;
    }

    if (count == 200) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    printf("%ld", quotients[0]);
    for (int i = 1; i < count; i++) {
        printf("; %ld", quotients[i]);
    }
    puts("");
    return 0;
}
